private void ClearSteamCache_Click(object sender, RoutedEventArgs e)
{
    var confirm = MessageBox.Show("Are you sure you want to clear the Steam Workshop cache?", 
        "Clear Cache", MessageBoxButton.YesNo, MessageBoxImage.Warning);

    if (confirm != MessageBoxButton.Yes) return;

    try
    {
        string appData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        string cachePath = Path.Combine(appData, "PZWorkshopDownloader", "steamcmd", "workshop", "content", "108600");

        if (Directory.Exists(cachePath))
        {
            foreach (string dir in Directory.GetDirectories(cachePath))
            {
                Directory.Delete(dir, true);
            }
            foreach (string file in Directory.GetFiles(cachePath))
            {
                File.Delete(file);
            }
            AppendLog("Steam Workshop cache cleared.");
            StatusText.Text = "Workshop cache cleared.";
        }
        else
        {
            AppendLog("Workshop cache directory not found.", "WARNING");
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show($"Failed to clear cache: {ex.Message}");
        AppendLog($"Failed to clear workshop cache: {ex.Message}", "ERROR");
    }
}

